const key='biod-v1';let db=JSON.parse(localStorage.getItem(key)||'null')||{clients:[],visits:[],orders:[],payments:[],opportunities:[],products:[],plans:[]};let current='home';const ids={clients:'العملاء',visits:'الزيارات',orders:'طلبات البيع',payments:'التحصيل',opportunities:'فرص البيع',products:'المنتجات والأسعار',plans:'الخطة والتارجت'};const schemas={clients:[['name','اسم العميل','text'],['phone','الهاتف','tel'],['area','المنطقة','text'],['opening','الرصيد الافتتاحي','number'],['lat','خط العرض','number'],['lng','خط الطول','number']],visits:[['client','العميل','client'],['date','موعد الزيارة','datetime-local'],['result','النتيجة','text'],['next','المتابعة القادمة','date']],orders:[['client','العميل','client'],['date','التاريخ','date'],['product','المنتج','product'],['qty','الكمية','number'],['price','سعر الوحدة','number'],['status','الحالة','مسجل|قيد التجهيز|تم التسليم|ملغي'],['due','استحقاق السداد','date']],payments:[['client','العميل','client'],['date','التاريخ','date'],['amount','المبلغ','number'],['method','الطريقة','نقدي|تحويل بنكي|شيك'],['reference','رقم الإثبات','text'],['proof','صورة الإثبات','file'],['status','المراجعة','في انتظار الاعتماد|معتمد|مرفوض']],opportunities:[['client','العميل','client'],['stage','المرحلة','عرض سعر|عينة للتجربة|تفاوض|تم البيع|مغلقة'],['notes','الخطوة القادمة','text'],['next','موعد المتابعة','date']],products:[['name','المنتج','text'],['price','السعر','number']],plans:[['date','بداية الفترة','date'],['end','نهاية الفترة','date'],['notes','خطة العمل','text'],['target','تارجت المبيعات','number'],['collectionTarget','تارجت التحصيل','number']]};const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>Number(n||0).toLocaleString('ar-EG')+' ج.م';const cname=id=>db.clients.find(c=>c.id===id)?.name||'عميل محذوف';function persist(){localStorage.setItem(key,JSON.stringify(db))}function balance(id){return db.clients.filter(c=>c.id===id).reduce((n,c)=>n+Number(c.opening||0),0)+db.orders.filter(o=>o.client===id&&o.status==='تم التسليم').reduce((n,o)=>n+o.qty*o.price,0)-db.payments.filter(p=>p.client===id&&p.status==='معتمد').reduce((n,p)=>n+Number(p.amount),0)}function mount(){document.querySelector('main').hidden=true;document.getElementById('workspace').hidden=false;render()}function render(){const root=document.getElementById('workspace');root.innerHTML=`<header class="bar"><b>BIO-D Sales</b><button id="logout">خروج</button></header><div class="layout"><nav>${[['home','بداية اليوم'],...Object.entries(ids),['dues','المستحقات'],['map','الخريطة وخط السير'],['reports','التقارير'],['manager','لوحة المدير'],['backup','النسخ الاحتياطي']].map(([k,v])=>`<button data-nav="${k}" class="${current===k?'active':''}">${v}</button>`).join('')}</nav><section class="content"><h1>${ids[current]||({home:'بداية اليوم',dues:'التحصيلات المستحقة',map:'خريطة العملاء وخط السير',reports:'التقارير',manager:'لوحة المدير',backup:'النسخ الاحتياطي'}[current])}</h1><div id="view"></div></section></div>`;root.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{current=b.dataset.nav;render()});document.getElementById('logout').onclick=()=>{root.hidden=true;document.querySelector('main').hidden=false};if(ids[current])list();else if(current==='home'||current==='manager')dashboard();else if(current==='dues')dues();else if(current==='map')route();else if(current==='reports')reports();else backup()}
function dashboard(){const view=document.getElementById('view');view.innerHTML=`<div class="cards"><article>العملاء<strong>${db.clients.length}</strong></article><article>المبيعات المسلمة<strong>${money(db.orders.filter(o=>o.status==='تم التسليم').reduce((n,o)=>n+o.qty*o.price,0))}</strong></article><article>التحصيل المعتمد<strong>${money(db.payments.filter(p=>p.status==='معتمد').reduce((n,p)=>n+Number(p.amount),0))}</strong></article><article>دفعات للمراجعة<strong>${db.payments.filter(p=>p.status==='في انتظار الاعتماد').length}</strong></article></div><h2>المتابعات القادمة</h2>${db.visits.filter(v=>v.next).sort((a,b)=>a.next.localeCompare(b.next)).map(v=>`<article>${esc(cname(v.client))} · ${esc(v.next)} · ${esc(v.result)}</article>`).join('')||'<p>ابدأ بإضافة العملاء والمنتجات، وبعدها سجل الزيارات والطلبات.</p>'}<p class="hint">البيانات على هذا الجهاز. لوحة المدير للمراجعة المحلية.</p>`}
function list(){const type=current;document.getElementById('view').innerHTML=`<div class="toolbar"><button id="add">إضافة</button><input id="search" placeholder="بحث بالاسم أو أي بيانات"></div><div id="rows"></div>`;document.getElementById('add').onclick=()=>edit(type);const draw=()=>{const q=document.getElementById('search').value.toLowerCase();document.getElementById('rows').innerHTML=db[type].filter(r=>JSON.stringify({...r,client:cname(r.client)}).toLowerCase().includes(q)).map(r=>`<article><h3>${esc(r.name||cname(r.client)||r.notes)}</h3>${schemas[type].filter(([k])=>k!=='proof'&&k!=='client').map(([k,l])=>`<div>${l} — ${esc(r[k])}</div>`).join('')}${type==='clients'?`<b>الرصيد المعتمد ${money(balance(r.id))}</b>`:''}${type==='orders'?`<b>الإجمالي ${money(r.qty*r.price)}</b>`:''}${r.proof?`<a href="${r.proof}" download="payment-proof">تحميل إثبات الدفعة</a>`:''}<div class="toolbar"><button data-edit="${r.id}">تعديل</button><button data-delete="${r.id}">حذف</button></div></article>`).join('')||'<p>لا توجد سجلات مطابقة.</p>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(type,b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(type==='clients'&&['visits','orders','payments','opportunities'].some(t=>db[t].some(r=>r.client===b.dataset.delete)))return alert('العميل له معاملات مسجلة. احتفظ بملفه للحفاظ على السجلات.');if(confirm('حذف السجل؟')){db[type]=db[type].filter(r=>r.id!==b.dataset.delete);persist();draw()}})};document.getElementById('search').oninput=draw;draw()}
function edit(type,id){const old=db[type].find(r=>r.id===id)||{};const dlg=document.getElementById('editor');dlg.innerHTML=`<form id="record"><h2>${id?'تعديل':'إضافة'} ${ids[type]}</h2>${schemas[type].map(([k,l,t])=>{let field;if(t==='client'||t==='product'){const data=t==='client'?db.clients:db.products;field=`<select name="${k}" required><option value="">اختيار</option>${data.map(x=>`<option value="${x.id}" ${old[k]===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`}else if(t.includes('|'))field=`<select name="${k}">${t.split('|').map(x=>`<option ${old[k]===x?'selected':''}>${x}</option>`).join('')}</select>`;else field=`<input name="${k}" type="${t}" ${t==='file'?'accept="image/*"':`value="${esc(old[k]??'')}"`} ${t==='number'?'step="any"':''} ${['name','date','qty','price','amount'].includes(k)?'required':''}>`;return `<label>${l}${field}</label>`}).join('')}${type==='clients'?'<button type="button" id="gps">حفظ موقعي الحالي GPS</button>':''}<p id="error" role="alert"></p><div class="toolbar"><button type="submit">حفظ</button><button type="button" id="cancel">إلغاء</button></div></form>`;dlg.showModal();document.getElementById('cancel').onclick=()=>dlg.close();if(type==='clients')document.getElementById('gps').onclick=()=>navigator.geolocation.getCurrentPosition(p=>{dlg.querySelector('[name=lat]').value=p.coords.latitude;dlg.querySelector('[name=lng]').value=p.coords.longitude},()=>alert('تعذر تحديد الموقع. اسمح بالموقع أو اكتب الإحداثيات يدوياً.'));if(type==='orders')dlg.querySelector('[name=product]').onchange=e=>{dlg.querySelector('[name=price]').value=db.products.find(p=>p.id===e.target.value)?.price||0};document.getElementById('record').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));const file=values.proof;delete values.proof;for(const [k,l,t]of schemas[type])if(t==='number'&&values[k]!==''&&Number(values[k])<0&&!['lat','lng'].includes(k)){document.getElementById('error').textContent='القيم المالية والكميات يجب أن تكون موجبة';return}if(type==='clients'&&((values.lat&&Math.abs(Number(values.lat))>90)||(values.lng&&Math.abs(Number(values.lng))>180)))return alert('الإحداثيات خارج النطاق');if(type==='orders'&&Number(values.qty)<=0)return alert('الكمية يجب أن تكون أكبر من صفر');if(type==='payments'&&Number(values.amount)<=0)return alert('المبلغ يجب أن يكون أكبر من صفر');if(file?.size){if(file.size>1500000)return alert('اختار صورة أقل من ١٫٥ ميجابايت');values.proof=await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file)})}const updated={...old,...values,id:old.id||crypto.randomUUID()};const before=JSON.stringify(db);if(id)db[type]=db[type].map(r=>r.id===id?updated:r);else db[type].push(updated);try{persist();dlg.close();render()}catch(err){db=JSON.parse(before);alert('مساحة التخزين غير كافية. صدّر نسخة احتياطية وقلل حجم المرفقات.')}}}
function dues(){document.getElementById('view').innerHTML=db.clients.filter(c=>balance(c.id)>0).map(c=>`<article><h3>${esc(c.name)}</h3><strong>${money(balance(c.id))}</strong>${db.orders.filter(o=>o.client===c.id&&o.status==='تم التسليم'&&o.due).map(o=>`<p>استحقاق طلب ${esc(o.due)} ${o.due<new Date().toISOString().slice(0,10)?'· متأخر':''}</p>`).join('')}</article>`).join('')||'<p>لا توجد أرصدة مستحقة.</p>'}
function route(){const clients=db.clients.filter(c=>c.lat!==''&&c.lat!=null&&c.lng!==''&&c.lng!=null);document.getElementById('view').innerHTML='<p>اختر العملاء المطلوب زيارتهم، ثم رتّبهم بدءاً من موقعك. الترتيب حسب المسافة الجغرافية التقريبية. الملاحة تحسب الطرق الفعلية.</p>'+clients.map(c=>`<label><input type="checkbox" name="stop" value="${c.id}" checked> ${esc(c.name)} <a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(c.lat+','+c.lng)}">عرض على الخريطة</a></label>`).join('')+'<button id="route">ترتيب الزيارات وفتح الاتجاهات</button><div id="stops"></div>';document.getElementById('route').onclick=()=>{const selected=[...document.querySelectorAll('[name=stop]:checked')].map(x=>clients.find(c=>c.id===x.value));if(!selected.length)return alert('اختار عميل واحد على الأقل');navigator.geolocation.getCurrentPosition(pos=>{let at={lat:pos.coords.latitude,lng:pos.coords.longitude},left=[...selected],sorted=[];while(left.length){left.sort((a,b)=>distance(at,a)-distance(at,b));at=left.shift();sorted.push(at)}const points=sorted.map(c=>c.lat+','+c.lng);document.getElementById('stops').innerHTML=sorted.map((c,i)=>`<article>${i+1}. ${esc(c.name)} <a target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(points[i])}&travelmode=driving">ابدأ الملاحة</a></article>`).join('')+`<p>عدد الزيارات ${sorted.length}. راجع مواعيد العملاء قبل الانطلاق.</p>`},()=>alert('فعّل إذن الموقع لتحديد بداية خط السير.'))}}
function distance(a,b){const rad=Math.PI/180;const dlat=(b.lat-a.lat)*rad,dlng=(b.lng-a.lng)*rad;return 6371*2*Math.asin(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dlng/2)**2))}
function reports(){document.getElementById('view').innerHTML='<div class="toolbar"><select id="period"><option value="day">يومي</option><option value="week">أسبوعي</option><option value="month">شهري</option><option value="quarter">ربع سنوي</option><option value="year">سنوي</option></select><input type="date" id="anchor" value="'+new Date().toISOString().slice(0,10)+'"><button id="generate">عرض التقرير</button></div><div id="report"></div><div class="toolbar"><button id="print">طباعة / حفظ PDF</button><button id="share">مشاركة التقرير</button></div>';let text='';function generate(){let start=new Date(document.getElementById('anchor').value+'T00:00:00'),end=new Date(start),p=document.getElementById('period').value;if(isNaN(start))return;if(p==='week'){start.setDate(start.getDate()-((start.getDay()+6)%7));end=new Date(start);end.setDate(end.getDate()+6)}if(p==='month'||p==='quarter'||p==='year'){start.setDate(1);if(p==='quarter')start.setMonth(Math.floor(start.getMonth()/3)*3);if(p==='year')start.setMonth(0);end=new Date(start);end.setMonth(end.getMonth()+({month:1,quarter:3,year:12}[p]));end.setDate(0)}const date=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');const from=date(start),to=date(end),inside=r=>r.date>=from&&r.date.slice(0,10)<=to;const sales=db.orders.filter(o=>inside(o)&&o.status==='تم التسليم').reduce((n,o)=>n+o.qty*o.price,0),collection=db.payments.filter(x=>inside(x)&&x.status==='معتمد').reduce((n,x)=>n+Number(x.amount),0),plans=db.plans.filter(x=>x.date<=to&&(x.end||x.date)>=from);const target=plans.reduce((n,x)=>n+Number(x.target||0),0);text=`BIO-D Sales\nالتقرير من ${from} إلى ${to}\nالمبيعات المسلمة ${money(sales)}\nالتحصيل المعتمد ${money(collection)}\nالزيارات المسجلة ${db.visits.filter(inside).length}\nالخطة والتارجت للفترات المتداخلة مع التقرير\nتارجت المبيعات ${money(target)}\nتارجت التحصيل ${money(plans.reduce((n,x)=>n+Number(x.collectionTarget||0),0))}\n${plans.map(x=>x.date+' — '+(x.end||x.date)+' '+x.notes).join('\n')}`;document.getElementById('report').innerHTML='<article style="white-space:pre-wrap">'+esc(text)+'</article>'}document.getElementById('generate').onclick=generate;document.getElementById('print').onclick=()=>window.print();document.getElementById('share').onclick=async()=>{try{if(navigator.share)await navigator.share({title:'تقرير BIO-D Sales',text});else download('BIO-D-Report.txt',text,'text/plain')}catch(e){if(e.name!=='AbortError')alert('تعذرت المشاركة. استخدم الطباعة أو حمّل التقرير.')}};generate()}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function backup(){document.getElementById('view').innerHTML='<p>احتفظ بنسخة من بيانات هذا الجهاز بانتظام.</p><button id="export">تحميل نسخة احتياطية JSON</button><label>استعادة نسخة احتياطية<input id="import" type="file" accept="application/json"></label>';document.getElementById('export').onclick=()=>download('BIO-D-Backup.json',JSON.stringify(db),'application/json');document.getElementById('import').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(!Object.keys(db).every(k=>Array.isArray(data[k])&&data[k].every(r=>typeof r==='object'&&r!==null&&typeof r.id==='string')))throw Error();if(confirm('استبدال بيانات الجهاز بالنسخة المختارة؟')){const previous=db;db=data;try{persist()}catch(e){db=previous;throw e}render()}}catch(e){alert('تعذرت الاستعادة. تحقق من الملف ومساحة التخزين.')}}}
document.getElementById('login').onclick=mount;
